import{_ as s,o as n,c as p,a2 as t}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"04i · 蜂蜜黄油味无包装镜头 v2 优化","description":"","frontmatter":{},"headers":[],"relativePath":"lab/shuangyu-fries/04i-honey-butter-v2-optimization.md","filePath":"lab/shuangyu-fries/04i-honey-butter-v2-optimization.md","lastUpdated":1786871523000}'),e={name:"lab/shuangyu-fries/04i-honey-butter-v2-optimization.md"};function l(i,a,o,d,c,r){return n(),p("div",null,[...a[0]||(a[0]=[t(`<h1 id="_04i-·-蜂蜜黄油味无包装镜头-v2-优化" tabindex="-1">04i · 蜂蜜黄油味无包装镜头 v2 优化 <a class="header-anchor" href="#_04i-·-蜂蜜黄油味无包装镜头-v2-优化" aria-label="Permalink to &quot;04i · 蜂蜜黄油味无包装镜头 v2 优化&quot;">​</a></h1><blockquote><p>阶段 4 · 第一轮成图复盘后修订 ｜ 2026-08-13 ｜ 对应本地生成结果 <code>images/黄油蜂蜜味/</code></p><p>本页只优化 <strong>镜头 01–05 的无包装部分</strong>。镜头 06 的包装合成流程不变，继续使用真实终稿包装。</p></blockquote><h2 id="结论先行" tabindex="-1">结论先行 <a class="header-anchor" href="#结论先行" aria-label="Permalink to &quot;结论先行&quot;">​</a></h2><p>第一轮不是画质不足，而是两个基础设定把整组画面带偏了：</p><ol><li><strong>产品母版错误</strong>：现有主体更像挤压膨化棒、威化棒或粗饼干，四角过圆、表面均匀鼓泡、端面像发泡组织；没有鲜切马铃薯条应有的平直切面、纵向自然纹理和不规则马铃薯孔隙。</li><li><strong>风味语言重复</strong>：金色半透明光带在关键帧 1–4 中反复缠绕产品，且穿过手部和食物。单张有视觉冲击，连续剪辑会像同一特效换背景，蜂蜜、黄油、调味和脆感没有各自的镜头职责。</li></ol><p>因此 v2 不在原图上继续增加特效。先重做产品定妆，再按 <strong>甜香靠近 → 奶油柔光 → 调味落附 → 干净脆裂 → 三次连击</strong> 五个独立视觉动作生成。</p><h2 id="第一轮逐张评估" tabindex="-1">第一轮逐张评估 <a class="header-anchor" href="#第一轮逐张评估" aria-label="Permalink to &quot;第一轮逐张评估&quot;">​</a></h2><table tabindex="0"><thead><tr><th>素材</th><th>可保留</th><th>主要问题</th><th>处理</th></tr></thead><tbody><tr><td>关键帧 1</td><td>黑底、中央主体、暖金轮廓</td><td>产品像膨化棒；光带数量过多并穿过主体；右下有平台水印</td><td><strong>重跑，作为新产品母版</strong></td></tr><tr><td>关键帧 2</td><td>明亮奶油色调</td><td>高光过曝；光幕变成半透明丝带并缠住食物；仍是膨化棒</td><td><strong>重跑，只保留色温</strong></td></tr><tr><td>关键帧 3</td><td>黑金对比</td><td>多出第二根产品与白色展台；与落粉镜头不符；继续重复光带</td><td><strong>废弃，重做为真正调味微距</strong></td></tr><tr><td>关键帧 4</td><td>折断动作可读，手部结构基本正常</td><td>手占画面过大；断面像面包/发泡饼干；光带穿手穿产品；碎屑过密</td><td><strong>重跑，改机械夹具或只露两枚指尖</strong></td></tr><tr><td>关键帧 5</td><td>三段节拍概念能看懂</td><td>三个动作塞进一张图，产品比例漂移；碎屑圆环像摆拍装饰；不利于视频模型理解动作</td><td><strong>拆成 05A / 05B / 05C 三张</strong></td></tr><tr><td>关键帧 6</td><td>左侧文案区和右侧杯位合理，布光可用于包装落版</td><td>前景产品仍是错误母版；粉末圆环像人为摆出的法阵</td><td><strong>包装段暂保留构图，后期替换前景产品</strong></td></tr><tr><td>v1-1.mp4</td><td>微距景别可用作节奏参考</td><td>表面有湿润油光和规则鼓泡，像刚炸出的膨化物</td><td><strong>不采用画面</strong></td></tr><tr><td>v1-2.mp4</td><td>浅色影棚方向可用</td><td>断裂后静止躺平，缺少断裂瞬间；主体仍像饼干棒</td><td><strong>不采用画面</strong></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">第一轮可以留下什么</p><p>保留 <strong>黑金开场 → 奶油白展开 → 黑底脆裂 → 明亮高潮</strong> 的明暗节奏。不要保留现有产品母版、重复光带和碎屑圆环。</p></div><h2 id="v2-产品母版锁定" tabindex="-1">v2 产品母版锁定 <a class="header-anchor" href="#v2-产品母版锁定" aria-label="Permalink to &quot;v2 产品母版锁定&quot;">​</a></h2><p>后续所有图片都先上传：</p><ul><li><strong>形态参考</strong>：项目产品图 <code>docs/lab/shuangyu-fries/assets/shu_tiao_cui.jpg</code>，只参考包装画面中的薯条形态，不参考番茄红色颗粒。</li><li><strong>错误参考</strong>：<code>images/黄油蜂蜜味/关键帧1.png</code>，仅用于告诉模型保持原来的长度和构图尺度，明确要求纠正食物材质。</li></ul><p>每一条 v2 Prompt 都附上以下固定段，不要删减：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>同一款由鲜切马铃薯制成的粗条状薯条脆，长约 8–9 厘米，横截面约 9×10 毫米；</span></span>
<span class="line"><span>整体是平直的长方体条状，四条纵向棱线清楚但略有自然缺口，端部接近垂直平切，</span></span>
<span class="line"><span>不是圆头、胶囊形或圆柱形；四个长面保留鲜切马铃薯形成的轻微纵向纹理、细小裂隙与不均匀浅孔，</span></span>
<span class="line"><span>表层薄而脆，不是均匀发泡的厚壳；颜色为自然浅金黄，表面干爽哑光，</span></span>
<span class="line"><span>只附着稀疏、细小、可辨认的奶油黄色调味粉与极少琥珀色颗粒。</span></span>
<span class="line"><span>断面是马铃薯脱水后的不规则细胞孔隙：孔洞大小不一、孔壁薄、局部仍较致密，</span></span>
<span class="line"><span>不是面包纤维、威化层、海绵、规则蜂巢或挤压膨化泡孔。</span></span></code></pre></div><p><strong>新增固定负面项：</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>挤压膨化棒，玉米棒，威化棒，饼干棒，米果，面包棒，鱼条，鸡块，</span></span>
<span class="line"><span>胶囊形，圆柱形，圆头，四角全部磨圆，均匀密集鼓泡，发泡塑料，</span></span>
<span class="line"><span>湿润表面，糖浆光泽，油膜，高亮反射，橙红调味粉。</span></span></code></pre></div><h2 id="v2-生成策略" tabindex="-1">v2 生成策略 <a class="header-anchor" href="#v2-生成策略" aria-label="Permalink to &quot;v2 生成策略&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">顺序</th><th>任务</th><th>参考图</th><th>通过后才能做什么</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td><strong>P0 产品校准帧</strong></td><td>项目产品图 + 关键帧 1</td><td>P0 通过后才做全部镜头</td></tr><tr><td style="text-align:right;">2</td><td>01 甜香靠近</td><td>P0</td><td>锁定黑底产品色温</td></tr><tr><td style="text-align:right;">3</td><td>04A / 04B 脆裂首尾帧</td><td>P0</td><td>锁定真实断面与产品强度</td></tr><tr><td style="text-align:right;">4</td><td>03 风味落脆</td><td>P0</td><td>锁定调味粉尺度与颜色</td></tr><tr><td style="text-align:right;">5</td><td>02 黄油柔光</td><td>P0</td><td>锁定明亮段落色温</td></tr><tr><td style="text-align:right;">6</td><td>05A / 05B / 05C 连击</td><td>P0 + 04B</td><td>分别生成视频后剪辑</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">不要拿现有关键帧 1 继续衍生</p><p>它已经把“均匀发泡的膨化棒”锁进模型。v2 的所有镜头必须改用通过验收的 P0；否则背景和特效会改善，产品仍然错误。</p></div><h2 id="p0-·-产品校准帧" tabindex="-1">P0 · 产品校准帧 <a class="header-anchor" href="#p0-·-产品校准帧" aria-label="Permalink to &quot;P0 · 产品校准帧&quot;">​</a></h2><p><strong>用途</strong>：只校准食物，不追求创意特效。生成 4 张，只选一张作为 v2 全片唯一产品母版。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Use case: ads-marketing</span></span>
<span class="line"><span>Asset type: honey-butter potato crisp appearance master reference</span></span>
<span class="line"><span>Input images:</span></span>
<span class="line"><span>- Image 1: the project product rendering; use only the visible potato-stick geometry and fresh-cut character,</span></span>
<span class="line"><span>  ignore all packaging, text, tomato flavor and red seasoning</span></span>
<span class="line"><span>- Image 2: first-round keyframe 1; use only subject length and framing scale,</span></span>
<span class="line"><span>  explicitly correct its puffed-extruded texture and rounded shape</span></span>
<span class="line"><span></span></span>
<span class="line"><span>真实高端食品摄影。中性浅灰影棚背景中，一根由鲜切马铃薯制成的粗条状薯条脆</span></span>
<span class="line"><span>以三分之四角度平放在深灰哑光石板上，完整呈现顶部、侧面和一个平切端面。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>同一款由鲜切马铃薯制成的粗条状薯条脆，长约 8–9 厘米，横截面约 9×10 毫米；</span></span>
<span class="line"><span>整体是平直的长方体条状，四条纵向棱线清楚但略有自然缺口，端部接近垂直平切，</span></span>
<span class="line"><span>不是圆头、胶囊形或圆柱形；四个长面保留鲜切马铃薯形成的轻微纵向纹理、细小裂隙与不均匀浅孔，</span></span>
<span class="line"><span>表层薄而脆，不是均匀发泡的厚壳；颜色为自然浅金黄，表面干爽哑光，</span></span>
<span class="line"><span>只附着稀疏、细小、可辨认的奶油黄色调味粉与极少琥珀色颗粒。</span></span>
<span class="line"><span>平切端面显示不规则细胞孔隙，孔洞大小不一、孔壁薄、局部仍较致密。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>85mm macro lens, f/5.6，机位略高于石板，柔和左前主光与右后窄轮廓光，</span></span>
<span class="line"><span>白平衡中性，真实马铃薯浅金色，无创意特效，无悬浮，无碎屑。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>禁止：包装、文字、logo、平台水印、蜂蜜、黄油块、光带、光环、烟雾；</span></span>
<span class="line"><span>挤压膨化棒，玉米棒，威化棒，饼干棒，米果，面包棒，鱼条，鸡块，</span></span>
<span class="line"><span>胶囊形，圆柱形，圆头，四角全部磨圆，均匀密集鼓泡，发泡塑料，</span></span>
<span class="line"><span>湿润表面，糖浆光泽，油膜，高亮反射，橙红调味粉，规则蜂巢，面包纤维。</span></span></code></pre></div><p><strong>P0 硬验收：</strong></p><ul><li>四条纵向棱线至少可见三条，端面接近平切，不是圆头。</li><li>顶部和侧面纹理不同且不规则，不是一层均匀气泡壳。</li><li>至少一个端面可读为马铃薯细胞孔隙，不像面包或海绵。</li><li>表面以漫反射为主，不出现连续湿亮高光。</li><li>仍然像零食且有食欲，不能为了“真实”变成生马铃薯条。</li></ul><h2 id="_01-·-甜香靠近" tabindex="-1">01 · 甜香靠近 <a class="header-anchor" href="#_01-·-甜香靠近" aria-label="Permalink to &quot;01 · 甜香靠近&quot;">​</a></h2><p><strong>单一信息</strong>：温暖甜香正在靠近。此镜只允许一处琥珀光，不再用多条缠绕丝带。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Use case: ads-marketing</span></span>
<span class="line"><span>Asset type: opening keyframe, no packaging</span></span>
<span class="line"><span>Input image: approved P0 as strict product identity reference</span></span>
<span class="line"><span></span></span>
<span class="line"><span>纯黑影棚中，同一根薯条脆水平悬浮在画面中央，保持 P0 的长方体轮廓、平切端面、</span></span>
<span class="line"><span>浅金色和干爽马铃薯纹理。产品后方约一根产品宽度处，只有一道失焦的椭圆琥珀色反射光</span></span>
<span class="line"><span>从左向右缓慢接近，像暖色灯光扫过空气；它没有明确边缘，不是丝带、液体、烟或实体。</span></span>
<span class="line"><span>产品前方与表面保持完全干净，只有窄幅暖金轮廓光扫过上缘。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>100mm macro lens, f/4，正侧面，主体占画面宽度 48%，黑色负空间充足，</span></span>
<span class="line"><span>克制、安静、真实商业食品摄影。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>禁止第二根产品、碎屑、光带缠绕、星芒、金粉、光线穿过产品、蜂蜜液体、</span></span>
<span class="line"><span>湿亮表面、包装、文字、logo、平台水印；严格保持 P0 产品身份。</span></span></code></pre></div><p>**视频动作：**背景椭圆光斑在 2.8 秒内移动约画面宽度 18%；产品只做 2% 缓慢推进，不旋转、不变形。</p><h2 id="_02-·-黄油柔光" tabindex="-1">02 · 黄油柔光 <a class="header-anchor" href="#_02-·-黄油柔光" aria-label="Permalink to &quot;02 · 黄油柔光&quot;">​</a></h2><p><strong>单一信息</strong>：黄油般圆润柔和的风味。此镜只用面积光变化，不出现实体黄油或任何流体。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Use case: ads-marketing</span></span>
<span class="line"><span>Asset type: butter-soft light keyframe, no packaging</span></span>
<span class="line"><span>Input image: approved P0 as strict product identity reference</span></span>
<span class="line"><span></span></span>
<span class="line"><span>明亮奶油白无缝影棚中，同一根薯条脆由左下向右上形成约 15 度斜线，</span></span>
<span class="line"><span>保持 P0 的平直长方体、平切端面与干爽表面。背景是一块宽阔、无边界、失焦的奶油黄色面积光，</span></span>
<span class="line"><span>由画面后方缓慢提亮；柔光只改变环境色温，不形成布料、薄膜、丝带或液体，也不覆盖产品。</span></span>
<span class="line"><span>产品下方有非常柔和的真实阴影，使它离台面约 2 厘米，而不是无重力漂浮。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>85mm lens, f/4，奶油白、自然浅金与极少琥珀色的克制色板，</span></span>
<span class="line"><span>高光不过曝，顶部纹理和侧面棱线均保留细节，真实食品摄影。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>禁止丝带、透明膜、布褶、流体、黄色酱汁、黄油块、光线缠住产品、金粉、星芒、</span></span>
<span class="line"><span>全白过曝、湿亮表面、包装、文字、logo、平台水印；严格保持 P0 产品身份。</span></span></code></pre></div><p>**视频动作：**面积光从 35% 提升到 55% 亮度，产品平稳向右上移动约自身长度的 25%；禁止自转。</p><h2 id="_03-·-风味落脆" tabindex="-1">03 · 风味落脆 <a class="header-anchor" href="#_03-·-风味落脆" aria-label="Permalink to &quot;03 · 风味落脆&quot;">​</a></h2><p><strong>单一信息</strong>：真实调味粉落下并附着。此镜不出现任何光带。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Use case: ads-marketing</span></span>
<span class="line"><span>Asset type: seasoning macro keyframe, no packaging</span></span>
<span class="line"><span>Input image: approved P0 as strict product identity reference</span></span>
<span class="line"><span></span></span>
<span class="line"><span>镜头贴近同一根薯条脆一个纵向棱角，棱线从左下延伸到右上；画面中同时看见顶部与侧面，</span></span>
<span class="line"><span>两者保持 P0 的不同自然纹理。约 20–30 颗可数的真实食品调味颗粒从上方落下：</span></span>
<span class="line"><span>大部分是极细奶油黄色粉末，少量是 0.3–0.8 毫米的浅琥珀色不规则颗粒；</span></span>
<span class="line"><span>其中三四颗刚接触表面，一颗在棱角处弹起，其余自然停留在浅裂隙内。</span></span>
<span class="line"><span>颗粒不发光，没有螺旋轨迹、圆环、爆炸或烟尘。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>100mm macro lens, 1000fps freeze frame, f/5.6，焦点覆盖接触点与纵向棱线，</span></span>
<span class="line"><span>暖白背景，侧逆光只勾亮颗粒边缘，产品表面保持干爽漫反射。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>禁止第二根产品、整块食物碎屑、金粉、发光颗粒、珠宝、玻璃、光带、烟雾、粉尘云、</span></span>
<span class="line"><span>液体、油滴、湿亮表面、包装、文字、logo、平台水印；严格保持 P0 产品身份。</span></span></code></pre></div><p>**视频动作：**只生成 1.5–2 秒落粉动作；颗粒受重力垂直落下，接触后最多弹跳一次，禁止围绕主体旋转。</p><h2 id="_04a-04b-·-一折即脆" tabindex="-1">04A / 04B · 一折即脆 <a class="header-anchor" href="#_04a-04b-·-一折即脆" aria-label="Permalink to &quot;04A / 04B · 一折即脆&quot;">​</a></h2><p><strong>单一信息</strong>：真实鲜切薯条脆的清脆断裂。优先使用两枚小型不锈钢食品测试夹具，避免第一轮双手抢画面。</p><h3 id="_04a-首帧" tabindex="-1">04A 首帧 <a class="header-anchor" href="#_04a-首帧" aria-label="Permalink to &quot;04A 首帧&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Use case: ads-marketing</span></span>
<span class="line"><span>Asset type: crisp-break start frame, no packaging</span></span>
<span class="line"><span>Input image: approved P0 as strict product identity reference</span></span>
<span class="line"><span></span></span>
<span class="line"><span>深炭黑影棚中，同一根薯条脆水平位于画面中央，严格保持 P0 的平直长方体、平切端面、</span></span>
<span class="line"><span>纵向自然纹理和干爽表面。画面左右边缘各有一枚窄小的哑光不锈钢食品测试夹具，</span></span>
<span class="line"><span>分别夹住产品最外侧约 8 毫米；夹具只占画面宽度 8%，不出现手或机械臂。</span></span>
<span class="line"><span>产品中央完整、笔直、尚未受力，断裂区域处于最清晰焦平面。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>100mm macro lens, f/5.6，固定正侧机位，强侧逆光勾出棱线，柔和正面补光保留马铃薯色泽，</span></span>
<span class="line"><span>背景纯净，无光带、无碎屑、无星芒。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>禁止手、额外夹具、产品弯曲、预先裂开、光线穿过产品、湿亮表面、</span></span>
<span class="line"><span>包装、文字、logo、平台水印；严格保持 P0 产品身份。</span></span></code></pre></div><h3 id="_04b-尾帧" tabindex="-1">04B 尾帧 <a class="header-anchor" href="#_04b-尾帧" aria-label="Permalink to &quot;04B 尾帧&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Use case: ads-marketing</span></span>
<span class="line"><span>Asset type: crisp-break end frame, no packaging</span></span>
<span class="line"><span>Input images: approved 04A as strict composition reference; approved P0 as product-material reference</span></span>
<span class="line"><span></span></span>
<span class="line"><span>保持 04A 的画幅、机位、焦距、夹具位置、产品尺度和灯光完全不变；</span></span>
<span class="line"><span>只把中央完整薯条脆改为刚刚断裂后的状态。左右两段沿水平方向分开 12–15 毫米，</span></span>
<span class="line"><span>没有弯曲或扭转；两个不规则断口略朝镜头，显示马铃薯脱水后的大小不一细胞孔隙、薄孔壁和局部致密组织。</span></span>
<span class="line"><span>从断裂点飞出 8–12 枚可辨认的浅金色薄片状碎屑，大小 0.5–4 毫米，</span></span>
<span class="line"><span>主要沿断裂方向向左右和轻微向前运动，不形成粉尘云或爆炸球。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>100mm macro lens, 1000fps freeze frame, f/5.6，断口与主要碎屑清晰，背景深炭黑。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>禁止面包纤维、海绵、规则蜂巢、挤压泡孔、巨大洞穴、碎屑爆炸、烟雾、金粉、</span></span>
<span class="line"><span>夹具变形、产品比例变化、光带、湿亮表面、包装、文字、logo、平台水印。</span></span></code></pre></div><p>**视频动作：**前 0.6 秒夹具各向外移动 2–3 毫米并施力；产品先出现一条局部裂纹，随后一次性断开。断裂后两段只分开 15 毫米并停住，不掉落、不变成软条。</p><h2 id="_05a-05b-05c-·-咔嚓连击" tabindex="-1">05A / 05B / 05C · 咔嚓连击 <a class="header-anchor" href="#_05a-05b-05c-·-咔嚓连击" aria-label="Permalink to &quot;05A / 05B / 05C · 咔嚓连击&quot;">​</a></h2><p>不再生成“一张图同时发生三件事”。三段使用同一明亮奶油白台面、同一 70mm 镜头、同一右后暖金硬光，分别生成并后期剪成「咔、咔、咔嚓」。</p><h3 id="_05a-·-落台" tabindex="-1">05A · 落台 <a class="header-anchor" href="#_05a-·-落台" aria-label="Permalink to &quot;05A · 落台&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>同一款 P0 薯条脆从距奶油白哑光台面约 3 厘米处刚刚落下，</span></span>
<span class="line"><span>一端先接触台面，产品保持完整；接触点只弹起 3–5 枚薄片状真实食物碎屑。</span></span>
<span class="line"><span>70mm lens, f/5.6，轻微低机位，画面左侧动作区，右侧保留干净空间。</span></span>
<span class="line"><span>没有光带、碎屑圆环、调味粉云、第二根产品、包装、文字、logo 或平台水印。</span></span></code></pre></div><h3 id="_05b-·-轻碰" tabindex="-1">05B · 轻碰 <a class="header-anchor" href="#_05b-·-轻碰" aria-label="Permalink to &quot;05B · 轻碰&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>两根完全相同的 P0 薯条脆在奶油白影棚中以约 25 度夹角轻碰，</span></span>
<span class="line"><span>接触点位于画面中央，两根都保持完整且轮廓互不融合；只飞出 2–3 枚小碎屑。</span></span>
<span class="line"><span>70mm lens, f/5.6，固定机位，产品运动方向清楚，遵循惯性与重力。</span></span>
<span class="line"><span>没有光带、碎屑圆环、第三根产品、包装、文字、logo 或平台水印。</span></span></code></pre></div><h3 id="_05c-·-前景脆裂" tabindex="-1">05C · 前景脆裂 <a class="header-anchor" href="#_05c-·-前景脆裂" aria-label="Permalink to &quot;05C · 前景脆裂&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>使用批准的 04B 作为断面材质参考。一根 P0 薯条脆在奶油白影棚的画面右前方刚刚断裂，</span></span>
<span class="line"><span>两段沿一条清晰水平轴分开，断口朝向镜头；8–12 枚薄片状碎屑向镜头前方运动，</span></span>
<span class="line"><span>最近的一枚轻微失焦，断面和主体仍保持清晰。70mm lens, f/5.6，固定机位，</span></span>
<span class="line"><span>右后暖金硬光点亮碎屑边缘，最后一次冲击最大但不爆炸。</span></span>
<span class="line"><span>没有手、夹具、光带、碎屑圆环、包装、文字、logo 或平台水印。</span></span></code></pre></div><p>**视频统一动作约束：**每段只做一个动作，生成 2–3 秒；产品不能自转超过 15 度，不能拉伸、弯曲、融化或改变粗细。后期只取每段 0.5–0.9 秒的有效动作。</p><h2 id="包装段衔接" tabindex="-1">包装段衔接 <a class="header-anchor" href="#包装段衔接" aria-label="Permalink to &quot;包装段衔接&quot;">​</a></h2><p>本轮不重做包装段。现有关键帧 6 可作为构图草图，但正式合成前做两项替换：</p><ol><li>用 P0 外观重新生成或后期替换右下三根错误的膨化棒产品。</li><li>删除大理石台上的同心粉末圆环，保留干净接触阴影给真实杯装包装。</li></ol><p>从 05C 切入包装段时，以一枚向右运动的碎屑做动作匹配；落版后不再出现光带或声波回收动画，让包装稳定至少 1.6 秒。</p><h2 id="v2-验收" tabindex="-1">v2 验收 <a class="header-anchor" href="#v2-验收" aria-label="Permalink to &quot;v2 验收&quot;">​</a></h2><ul><li>[ ] 所有镜头只使用通过 P0 的鲜切马铃薯条脆母版，不再使用关键帧 1 的膨化棒母版。</li><li>[ ] 产品为平直长方体、端面接近平切、棱线清楚，不是圆头胶囊形。</li><li>[ ] 表面干爽，只有细小不规则孔与浅裂纹，没有连续油亮高光。</li><li>[ ] 01 只有一处失焦琥珀光；02 只有面积光；03 只有真实调味颗粒；04 只有脆裂；05 每段只有一个动作。</li><li>[ ] 断面是大小不一的马铃薯细胞孔隙，不是面包、威化、海绵或挤压发泡结构。</li><li>[ ] 碎屑数量可数、形状不规则并遵循重力，没有圆环、烟花或金属粒子。</li><li>[ ] 全部无包装镜头不出现文字、logo、假包装和平台水印；平台强制水印须在交付前裁切或后期清除。</li></ul><hr><p><strong>第一轮提示词</strong> ← <a href="./04g-honey-butter-keyframes">04g · 蜂蜜黄油味图片关键帧</a> ｜ <strong>导演执行稿</strong> ← <a href="./03e-honey-butter-sensory-film">03e · 蜂蜜黄油味独立感官创意片</a></p>`,60)])])}const u=s(e,[["render",l]]);export{g as __pageData,u as default};
